import unittest
from xarray.variable import Variable

class TestVariable(unittest.TestCase):
    def test_slice_indexing(self):
        v = Variable(['x'], [10, 20, 30, 40])
        sliced = v[1:3]
        self.assertEqual(sliced.dims, ('x',))
        self.assertEqual(sliced.data, [20, 30])

if __name__ == '__main__': unittest.main()

